// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: Ctrl+Shift+F toggles full screen for the pane you are in (chat, results or Python),
//          by clicking that pane's zoom button (zoom_button in reflex_kernel.py).
//          "The pane you are in" = the one holding keyboard focus, else the one last clicked.
// ---------------------------------------------------------------------------
(() => {
  let lastPane = null;
  const paneOf = (node) => (node instanceof Element ? node.closest("[data-pane]") : null);
  const visible = (pane) => pane && pane.isConnected && pane.offsetParent !== null;

  document.addEventListener("pointerdown", (event) => { lastPane = paneOf(event.target) || lastPane; }, true);

  // capture phase, so it also works while typing in a code cell or the chat box
  document.addEventListener("keydown", (event) => {
    if (!(event.ctrlKey && event.shiftKey && !event.altKey && !event.metaKey && event.code === "KeyF")) return;
    const zoomed = document.querySelector(".zoom-btn.is-on");
    const pane = [paneOf(document.activeElement), lastPane].find(visible);
    const button = zoomed || (pane && pane.querySelector(".zoom-btn")) || document.querySelector("[data-pane] .zoom-btn");
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    button.click();
  }, true);
})();
